import 'package:flutter/material.dart'; import '../data/income_database.dart'; import '../models/income_models.dart';
class IncomeEditor extends StatefulWidget{const IncomeEditor({super.key,this.record});final IncomeRecord? record;@override State<IncomeEditor> createState()=>_IncomeEditorState();}
class _IncomeEditorState extends State<IncomeEditor>{final amount=TextEditingController(),source=TextEditingController(),account=TextEditingController(),memo=TextEditingController();IncomeType type=IncomeType.salary;DateTime date=DateTime.now();bool saving=false;bool get accountUseful=>type==IncomeType.dividend||type==IncomeType.interest||type==IncomeType.salary||type==IncomeType.bonus;bool get accountRequired=>type==IncomeType.dividend;
 @override void initState(){super.initState();final r=widget.record;if(r!=null){amount.text=r.amount.toString();source.text=r.source??'';account.text=r.account??'';memo.text=r.memo??'';type=r.type;date=r.date;}}
 @override void dispose(){amount.dispose();source.dispose();account.dispose();memo.dispose();super.dispose();}
 Future<void> save() async {final parsed=int.tryParse(amount.text.replaceAll(RegExp(r'[^0-9]'),''));if(parsed==null||parsed<=0||(accountRequired&&account.text.trim().isEmpty)){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('필수 입력을 확인해주세요.')));return;}setState(()=>saving=true);final now=DateTime.now();final r=IncomeRecord(id:widget.record?.id,amount:parsed,date:date,type:type,source:source.text.trim().isEmpty?null:source.text.trim(),account:account.text.trim().isEmpty?null:account.text.trim(),memo:memo.text.trim().isEmpty?null:memo.text.trim(),createdAt:widget.record?.createdAt??now,updatedAt:now);if(r.id==null){await IncomeDatabase.instance.insert(r);}else{await IncomeDatabase.instance.update(r);}if(mounted)Navigator.pop(context,true);}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(widget.record==null?'수입 기록':'수입 수정')),body:ListView(padding:const EdgeInsets.all(20),children:[DropdownButtonFormField<IncomeType>(initialValue:type,decoration:const InputDecoration(labelText:'Type'),items:IncomeType.values.map((e)=>DropdownMenuItem(value:e,child:Text(e.label))).toList(),onChanged:(v)=>setState(()=>type=v!)),const SizedBox(height:16),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'금액',prefixText:'₩ ')),const SizedBox(height:16),TextField(controller:source,decoration:InputDecoration(labelText:switch(type){IncomeType.salary||IncomeType.bonus=>'회사 (Source)',IncomeType.dividend=>'종목/상품 (Source)',IncomeType.interest=>'상품 (Source)',IncomeType.appTech=>'앱/서비스 (Source)',_=>'Source'})),if(accountUseful)...[const SizedBox(height:16),TextField(controller:account,decoration:InputDecoration(labelText:accountRequired?'Account *':'Account (선택)'))],const SizedBox(height:16),ListTile(contentPadding:EdgeInsets.zero,title:const Text('날짜'),subtitle:Text(date.year.toString()+'.'+date.month.toString().padLeft(2,'0')+'.'+date.day.toString().padLeft(2,'0')),trailing:const Icon(Icons.calendar_month),onTap:() async {final p=await showDatePicker(context:context,initialDate:date,firstDate:DateTime(2000),lastDate:DateTime(2100));if(p!=null)setState(()=>date=p);}),TextField(controller:memo,maxLines:2,decoration:const InputDecoration(labelText:'메모 (선택)')),const SizedBox(height:24),FilledButton(onPressed:saving?null:save,child:Text(saving?'저장 중…':'저장'))]));}
